INSERT INTO products (category_id, name, slug, description_fr, description_en, ingredients_fr, ingredients_en, price, weight, stock_quantity, image_url, is_available, is_featured, created_at) VALUES
(1, 'Confiture de Mangue', 'confiture-de-mangue', 'Confiture artisanale préparée avec des mangues fraîches du Sénégal. Un délice sucré au goût authentique.', 'Artisanal jam made with fresh Senegalese mangoes. A sweet delight with authentic taste.', 'Mangue, sucre, citron', 'Mango, sugar, lemon', 2500, '250g', 50, 'confiture-mangue.jpg', TRUE, TRUE, '2024-01-15'),
(1, 'Confiture de Gingembre', 'confiture-de-gingembre', 'Une confiture épicée au gingembre frais, parfaite pour les amateurs de saveurs audacieuses.', 'A spicy jam made with fresh ginger, perfect for lovers of bold flavors.', 'Gingembre, sucre, citron', 'Ginger, sugar, lemon', 3000, '250g', 30, 'confiture-gingembre.jpg', TRUE, TRUE, '2024-01-15'),
(1, 'Confiture de Pamplemousse', 'confiture-de-pamplemousse', 'Confiture acidulée au pamplemousse, idéale pour le petit-déjeuner.', 'Tangy grapefruit jam, ideal for breakfast.', 'Pamplemousse, sucre', 'Grapefruit, sugar', 2800, '250g', 25, 'confiture-pamplemousse.jpg', TRUE, FALSE, '2024-01-15'),
(1, 'Confiture de Tamarin', 'confiture-de-tamarin', 'Confiture exotique au tamarin, un goût unique qui surprendra vos papilles.', 'Exotic tamarind jam, a unique taste that will surprise your taste buds.', 'Tamarin, sucre, épices', 'Tamarind, sugar, spices', 2500, '250g', 20, 'confiture-tamarin.jpg', TRUE, FALSE, '2024-01-15'),
(1, 'Confiture de Citron', 'confiture-de-citron', 'Confiture rafraîchissante au citron, parfaite pour accompagner vos thés.', 'Refreshing lemon jam, perfect to accompany your teas.', 'Citron, sucre, gingembre', 'Lemon, sugar, ginger', 2400, '250g', 35, 'confiture-citron.jpg', TRUE, FALSE, '2024-01-15'),
(1, 'Confiture de Papaye', 'confiture-de-papaye', 'Confiture de papaye, fruit tropical aux saveurs ensoleillées.', 'Papaya jam, a tropical fruit with sunny flavors.', 'Papaye, sucre, vanille', 'Papaya, sugar, vanilla', 2300, '250g', 40, 'confiture-papaye.jpg', TRUE, FALSE, '2024-01-15'),
(1, 'Confiture de Baobab', 'confiture-de-baobab', 'Confiture originale au fruit de baobab, riche en vitamine C.', 'Original jam made with baobab fruit, rich in vitamin C.', 'Pulpe de baobab, sucre', 'Baobab pulp, sugar', 3200, '250g', 15, 'confiture-baobab.jpg', TRUE, TRUE, '2024-01-15'),
(2, 'Jus de Bissap', 'jus-de-bissap', 'Jus traditionnel à base d\'hibiscus, rafraîchissant et riche en antioxydants.', 'Traditional hibiscus-based juice, refreshing and rich in antioxidants.', 'Bissap, sucre, eau', 'Hibiscus, sugar, water', 1500, '500ml', 100, 'jus-bissap.jpg', TRUE, TRUE, '2024-01-15'),
(2, 'Jus de Bouye', 'jus-de-bouye', 'Jus de baobab crémeux et nutritif, une boisson énergisante.', 'Creamy and nutritious baobab juice, an energizing drink.', 'Pulpe de bouye, sucre, eau', 'Baobab pulp, sugar, water', 2000, '500ml', 80, 'jus-bouye.jpg', TRUE, TRUE, '2024-01-15'),
(2, 'Jus de Gingembre', 'jus-de-gingembre', 'Jus de gingembre piquant et revigorant, excellent pour la santé.', 'Spicy and invigorating ginger juice, excellent for health.', 'Gingembre, citron, sucre, eau', 'Ginger, lemon, sugar, water', 1500, '500ml', 90, 'jus-gingembre.jpg', TRUE, FALSE, '2024-01-15'),
(3, 'Sirop de Gingembre', 'sirop-de-gingembre', 'Sirop concentré de gingembre à diluer dans de l\'eau ou des boissons.', 'Concentrated ginger syrup to dilute in water or beverages.', 'Gingembre, sucre, citron', 'Ginger, sugar, lemon', 3000, '500ml', 45, 'sirop-gingembre.jpg', TRUE, TRUE, '2024-01-15'),
(3, 'Sirop de Bissap', 'sirop-de-bissap', 'Sirop concentré de bissap pour préparer de délicieuses boissons.', 'Concentrated hibiscus syrup for preparing delicious drinks.', 'Bissap, sucre, citron', 'Hibiscus, sugar, lemon', 2500, '500ml', 60, 'sirop-bissap.jpg', TRUE, FALSE, '2024-01-15'),
(4, 'Poudre de Moringa', 'poudre-de-moringa', 'Poudre de feuilles de moringa, super-aliment riche en nutriments.', 'Moringa leaf powder, a nutrient-rich superfood.', 'Feuilles de moringa séchées', 'Dried moringa leaves', 2500, '250g', 40, 'poudre-moringa.jpg', TRUE, TRUE, '2024-01-15'),
